<?php declare(strict_types=1); header('Cache-Control:no-store,no-cache,must-revalidate,max-age=0'); ?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Evruni Guard</title><style>*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:transparent}body{pointer-events:none;font-family:Arial,sans-serif}.g{position:absolute;border-radius:10px;background:#070a12d9;backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border:1px solid #fff1;box-shadow:0 12px 35px #0005}.c{background:#05070cf5;backdrop-filter:blur(32px)}.b{position:absolute;left:2%;top:2%;padding:5px 8px;border-radius:99px;background:#070b13c7;border:1px solid #55ddff44;color:#8deaff;font:9px Arial}.t{position:absolute;left:50%;top:6%;transform:translate(-50%,-12px);opacity:0;padding:12px 16px;border-radius:14px;background:#0a0e19ee;border:1px solid #6de7ff44;color:#fff;font:12px Arial;transition:.18s}.t.on{opacity:1;transform:translate(-50%,0)}</style></head><body><div class="b">EVRUNI GUARD • OBS</div><div id="t" class="t">🔞 AI Guard активен</div><div id="r"></div><script>(()=>{const p=new URLSearchParams(location.hash.slice(1)),h=p.get('host')||'127.0.0.1',port=p.get('port')||'4455',pw=p.get('pass')||'',r=document.getElementById('r'),t=document.getElementById('t');let w;const B=a=>{let s='';a.forEach(x=>s+=String.fromCharCode(x));return btoa(s)},S=async s=>new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s))),A=async(p,s,c)=>B(await S(B(await S(p+s))+c));function beep(){try{const C=AudioContext||webkitAudioContext,a=new C,o=a.createOscillator(),g=a.createGain();o.frequency.value=880;g.gain.value=.0001;o.connect(g).connect(a.destination);o.start();g.gain.exponentialRampToValueAtTime(.15,a.currentTime+.01);g.gain.exponentialRampToValueAtTime(.0001,a.currentTime+.18);o.stop(a.currentTime+.2)}catch(_){}}function draw(boxes,doBeep){r.innerHTML='';(boxes||[]).forEach(x=>{const d=document.createElement('div');d.className='g '+(x.action==='cover'?'c':'');d.style.cssText+=`left:${x.x/10}%;top:${x.y/10}%;width:${x.w/10}%;height:${x.h/10}%;`;r.appendChild(d)});if(boxes?.length){t.classList.add('on');setTimeout(()=>t.classList.remove('on'),1500)}if(doBeep)beep()}function connect(){try{w=new WebSocket(`ws://${h}:${port}`,'obswebsocket.json')}catch(_){return}w.onmessage=async e=>{let m;try{m=JSON.parse(e.data)}catch(_){return}if(m.op===0){const d=m.d||{},id={rpcVersion:1};if(d.authentication)id.authentication=await A(pw,d.authentication.salt,d.authentication.challenge);w.send(JSON.stringify({op:1,d:id}))}else if(m.op===5&&m.d?.eventType==='CustomEvent'){const d=m.d.eventData?.eventData||m.d.eventData,x=d?.eventName==='EvruniCreator'?(d.eventData||d):d;if(x?.type==='guard')draw(x.boxes||[],!!x.beep);if(x?.type==='clear')r.innerHTML=''}};w.onclose=()=>setTimeout(connect,2500);w.onerror=()=>{}}connect()})();</script></body></html>